        Log::channel('contatti')->info('form contatti', $request->all());

		// Subject handling
		$subject = [
			1 => __("form.label_objectA"),
			2 => __("form.label_objectB"),
			3 => __("form.label_objectC"),
			4 => __("form.label_objectD"),
		];
		// Recipients
		$emailSubject = [
			1 => 'info@azzurrabagni.com',
			2 => 'info@azzurrabagni.com',
			3 => 'postvendita@azzurrabagni.com',
			4 => 'info@azzurrabagni.com',
		];

        /**
         * Invio mail
         */
        $mail = new ContactMail([
            'Oggetto' => $subject[(int)$request->object],
            'Nome' => $request->name,
            'Città' => $request->city,
            'Provincia' => $request->district,
            'Tipo utente' => $request->user_type,
            'Email' => $request->email,
            'Telefono' => $request->phone,
            'Messaggio' => $request->message,
        ]);
        $mail->subject('Richiesta informazioni da sito');
        $mail->replyTo($request->email);
        $mail->from(config('mail.from'));
        $mail->to($emailSubject[(int)$request->object]);
        if(config('mail.contatti.bcc') !== null && strlen(config('mail.contatti.bcc'))) {$mail->bcc(config('mail.contatti.bcc'));}
        // preview nel browser
        // echo $mail->render();exit;
        Mail::send($mail);

		// Newsletter
		/* if(isset($request->check_newsletter) && $request->check_newsletter === 'Y'){
			$newsletter = Newsletter::create(['email' => $request->email, 'with_contact' => 'Y']);
		} */

        /**
         * Salvo messaggio
         */
        $request->session()->flash('message' ,  __('form.msg_success'));


        /**
         * Risposta json o redirect
         */
        if($request->expectsJson()) {
            return response()->json([
                'success' => 1,
                'redirect' => route('contatti_success')
            ]);
        }

        return redirect(route('contatti_success'));

